<?php session_name('VS_CUSTOMER');session_start();if(isset($_SESSION['user_id'])&&($_SESSION['user_role']??'')==='user'){header('Location: dashboard.php');exit;}require_once 'includes/header.php'; ?>
<section class="auth-page"><div class="auth-image"><div><span class="eyebrow">VS TRAVELLS CUSTOMER PORTAL</span><h1>Your journey starts here.</h1><p>Sign in to browse vehicles, request bookings, pay after approval and manage your trips.</p></div></div><div class="auth-panel"><form id="loginForm" class="auth-form"><span class="eyebrow dark">CUSTOMER LOGIN</span><h2>Welcome to VS Travells</h2><p class="muted">Only registered customer accounts can sign in here.</p><div id="msg"></div><label>Email address<input type="email" id="email" required placeholder="you@example.com" value="customer@vstravells.com"></label><label>Password<input type="password" id="password" required placeholder="••••••••" value="Customer@123"></label><button class="btn wide">Customer sign in</button><div style="margin-top:14px;background:#f8fafc;padding:10px 14px;border-radius:10px;font-size:11px;color:#64748b;border:1px solid #e2e8f0;"><strong>Demo Customer Credentials:</strong><br>Email: <code>customer@vstravells.com</code><br>Password: <code>Customer@123</code></div><p class="auth-switch">New customer? <a href="register.php">Create an account</a></p></form></div></section>
<script>
const loginForm=document.getElementById('loginForm'),loginMsg=document.getElementById('msg');
loginForm.addEventListener('submit',async e=>{e.preventDefault();const email=document.getElementById('email').value.trim(),password=document.getElementById('password').value;try{const r=await fetch('api/auth/login.php',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({email,password})});const j=await r.json();loginMsg.innerHTML=`<div class="message ${j.success?'success':'error'}">${j.message}</div>`;if(j.success)setTimeout(()=>location.href='dashboard.php',450)}catch(_){loginMsg.innerHTML='<div class="message error">Unable to sign in. Please try again.</div>'}});
</script><?php require_once 'includes/footer.php'; ?>
